// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, bytes32 digest, bytes32 r, bytes32 s) public {
        vm.assume(!c.approvedToLog(caller));
        vm.prank(caller);
        bool ret = c.logGotRedemptionSignature(digest, r, s);
        assertTrue(ret == false, "Non-approved caller should return false");
    }
}

